from pathlib import Path
from shutil import copy2
from docx import Document
SRC=Path(r"outputs/chapter5_midterm_revision/第五章（中期验收版_修订_养护保留版）.docx")
OUT=Path(r"outputs/chapter5_midterm_revision/第五章（中期验收版_修订_对象动作一致版）.docx")
copy2(SRC,OUT)
TEXT={
'5.2.5':'清洁用品取放与归位任务是指围绕家庭日常清洁用品和垃圾投放开展的对象操作。本任务的已核验操作对象仅包括垃圾桶、饮料罐、海绵、清洁刷和清洁喷雾瓶五种。垃圾处理示教要求将客厅中的三罐汽水投入厨房垃圾桶；海绵示教要求从台面抓取海绵并放入橱柜；清洁刷示教要求从橱柜取出洗碗刷并放到台面；清洁喷雾瓶示教要求从橱柜取出喷雾瓶并放到台面。机器人执行时需要根据指令区分垃圾投放、柜体取物和柜体归位三种动作，识别台面、橱柜和垃圾桶之间的目标关系，保持夹爪抓取稳定，并通过视觉确认饮料罐已进入垃圾桶、用品已到达指定位置。该任务以清洁用品的规范取放和垃圾投放为核心，不包含其他清洁设备或清扫轨迹操作。',
'5.2.6':'厨房器具单件归位任务是指围绕已核验厨房对象开展取放、开合、推拉、分类和烹调辅助操作。本任务包括削皮刀、餐刀、砧板、平底锅、混合碗、打蛋器、擀面杖、炉灶、烤箱、烤面包机下层烤盘、烹饪托盘、玻璃罐、碗、茶壶、调味罐、量杯和锅等对象。刀具、砧板和碗对应将食材从水槽转移、在砧板处理并放入碗中的示教；平底锅对应在炉灶上完成蔬菜烹调；混合碗对应按类别分装蔬菜；烤箱门、烤盘和托盘对应关闭、推入或拉出动作；玻璃罐对应开柜、开罐、盛装、关罐和归回；打蛋器、擀面杖、茶壶、调味罐、量杯和锅对应台面、抽屉或橱柜之间的取放。机器人执行时需要依据对象形状、把手位置和目标容器完成相应操作。',
'5.2.7':'养护管理任务是指对表5-7所列家庭养护对象进行提醒、监测、控制和状态记录的操作。本任务仅包括灌溉系统、智能花盆或灌溉阀、摄像头与AI识别模块、花园灌溉系统、小型盆栽、智能体重秤、空气净化器、扫地机器人、烟雾报警器和燃气报警器十种对象。灌溉系统用于土壤湿度过低提醒，智能花盆或灌溉阀用于浇水开关控制，摄像头与AI用于识别植物病虫害，花园灌溉系统用于定时或湿度控制，小型盆栽用于位置调整。智能体重秤用于记录并上传体重数据，空气净化器用于滤网更换提醒，扫地机器人用于边刷和滤网更换提醒，烟雾报警器用于电量不足提醒，燃气报警器用于定期自检提醒。机器人执行时按照设备状态、时间信息和用户指令完成相应的提示、控制或记录。',
'5.2.8':'物品递送任务是指将已核验的指定物品从明确起点运送到明确终点的操作。本任务包括书籍、水瓶、盒装饮料、罐装物、饮料瓶和马克杯六种对象。书籍示教对应从卧室床上移动到床头柜；水瓶、盒装饮料、罐装物和马克杯示教均对应从橱柜取出并放到台面；饮料瓶示教对应从厨房冰箱取出两瓶饮料，带到客厅并放到咖啡台，同时完成冰箱关闭。机器人执行时需要先依据语言指令确定物品类别和起终点，再选择适当的抓取位置完成取物、移动和放置。对于饮料瓶等多个同类对象，应保持物品数量和落放位置与指令一致；对于杯具和罐装物，应保持末端姿态平稳，避免倾倒。任务完成后通过目标区域内的物体位置以及相关设施状态判断递送是否完成。',
'5.2.9':'整理收纳任务是指对已核验容器、书籍和收纳设施进行归位与分类的操作。本任务包括密封保鲜盒、床头柜、收纳盒、收纳箱、收纳篮和纸箱六种对象。密封保鲜盒示教对应从台面放入橱柜；收纳盒示教对应将盒装饮料从台面放入橱柜；床头柜示教对应接收从床上移来的书籍；收纳箱和纸箱示教对应将客厅书架上的六本书放入客厅地面的指定容器；收纳篮示教对应将卧室篮中的物品分类放入浴室指定区域。机器人执行时需要识别容器开口、目标储位和待整理物的类别，按照指令完成抓取、搬运和容器内放置。对于书籍与收纳箱、纸箱的操作，应确认全部指定书籍进入目标容器；对于收纳篮操作，应确认物品位于指定浴室区域。',
'5.2.10':'储物设施开合任务是指对家庭厨房和清洗区域的门、抽屉、层架和烤盘进行开合或推拉操作。本任务包括冰箱层架、冰箱抽屉、冰箱门、微波炉门、普通抽屉、橱柜门、洗碗机上层架、洗碗机门、烤箱门和烤面包机烤箱门十种对象。冰箱层架示教对应将苹果从冰箱抽屉放到层架；冰箱抽屉、冰箱门、微波炉门、普通抽屉、橱柜门、洗碗机门和烤箱门均对应关闭动作；洗碗机上层架对应完全推入动作；烤面包机烤箱门对应打开动作。机器人执行时需要根据把手、边缘和开口方向确定接触部位，沿正确方向施加平稳运动，并通过门缝、抽屉位置、层架行程或视觉状态确认操作结果。该任务的每个对象均具有明确的目标状态，可直接用于开合技能的验证。',
'5.2.11':'室内摆放任务是指对室内装饰物、墙面固定件和拍摄设备进行摆放、悬挂或连接的操作。本任务包括墙钉、数码相机、海报、相机三脚架和蜡烛五种对象。墙钉和海报示教对应将厨房台面的海报悬挂到指定墙钉；数码相机和相机三脚架示教对应将数码相机连接到卧室三脚架；蜡烛示教对应从橱柜取出并放到台面。机器人执行时需要识别墙钉位置、海报边缘、相机安装接口、三脚架承载位置以及台面摆放区域，选择与对象相适应的末端姿态。悬挂操作完成后应确认海报位于墙钉上；设备连接完成后应确认相机与三脚架保持稳定；蜡烛摆放完成后应确认其位于指定台面区域。任务描述和操作对象均以这五种已核验对象为准。',
'5.2.12':'餐具与容器摆放任务是指对厨房常用杯具、夹取工具、切配工具、勺具、盛装容器和过滤容器进行规范取放的操作。本任务包括咖啡杯、夹子、披萨刀、木勺、水罐、汤勺、洗碗刷、滤盆、盘子和铝箔纸十种对象。咖啡杯、夹子和披萨刀示教对应从橱柜取出并放到台面；木勺、水罐、汤勺、洗碗刷、滤盆和铝箔纸示教对应从台面取出并放入橱柜；盘子示教对应将平底锅中的苹果放到盘子上。机器人执行时需要根据杯口、夹口、刀柄、勺柄、容器边缘和滤盆开口选择抓取位置，按照指令完成台面与橱柜之间的转移，或完成平底锅到盘子的食材转移。放置时应保持杯具、刀具和容器方向稳定，避免与周围餐具发生碰撞。',
'5.2.13':'衣物鞋类与玄关归位任务是指对帽类、毛巾、鞋类、鞋架和洗衣机进行清洗、分类或归位的操作。本任务包括棒球帽、毛巾、洗衣机、鞋子和鞋架五种对象。棒球帽和洗衣机示教对应将工具间台面的两顶棒球帽放入洗衣机清洗，直至帽子不再处于脏污状态；毛巾示教对应将毛巾分入两个篮子；鞋子和鞋架示教对应将走廊地面的两双运动鞋和两双凉鞋放到走廊鞋架上，并使两双运动鞋相邻、两双凉鞋相邻。机器人执行时需要识别织物、鞋类和收纳位置的类别关系，保持鞋类配对和排列顺序。洗衣操作需要确认两顶帽子进入洗衣机并完成相应清洗状态；毛巾操作需要确认两组毛巾进入不同篮子；鞋类操作需要确认鞋子离开地面且位于鞋架指定区域。',
'5.2.14':'工作学习区服务任务是指对书桌、转椅及其周边的计算设备、输入设备、文件和文具进行摆放与整理的操作。本任务包括办公椅、文件夹、显示器、电脑、笔盒、笔记本、笔记本电脑、订书机、铅笔、键盘和鼠标十一种对象。办公椅示教对应移动到书桌旁；文件夹示教对应从转椅移到书桌并放在鼠标旁；显示器、键盘和鼠标分别放在书桌及相邻位置；电脑放在书桌下；笔记本叠放在文件夹上；笔盒用于收纳铅笔和两支笔并留在桌面；笔记本电脑从床上移到书桌并关闭；订书机从书柜移到桌面；铅笔放入笔盒。机器人执行时需要理解书桌、转椅、书柜和床的空间关系，并保持显示器、键盘、鼠标、文件夹和笔记本之间的相对位置符合指令。',
'5.2.15':'卫浴用品与个人卫生服务任务是指对浴室搁板、卫生巾盒、固体香皂、洗涤剂、牙刷、牙膏和皂液器进行取放与分类的操作。本任务的已核验对象仅包括这七种。卫浴搁板和卫生巾盒示教对应将卫生巾盒从卧室篮中放到浴室搁板；固体香皂示教对应从台面放入橱柜；洗涤剂示教对应从卧室篮中取出并放在洗手池下方；牙刷和牙膏示教对应放入洗手台上的杯中；皂液器示教对应从橱柜取出并放到台面。机器人执行时需要识别浴室搁板、洗手池下方、洗手台杯子、橱柜和台面等目标区域，按照指令保持卫生用品的相对位置。完成后应确认卫生巾盒位于搁板、洗涤剂位于洗手池下方、牙刷和牙膏在杯中、香皂与皂液器处于指定取放位置。'
}
d=Document(OUT)
for code,text in TEXT.items():
    i=next(i for i,p in enumerate(d.paragraphs) if p.text.strip().startswith(code))
    body=d.paragraphs[i+1]; body.clear(); body.add_run(text)
d.save(OUT); print('rewritten',OUT)
